use spirq::{ReflectConfig,SpirvBinary,Variable};
fn u(bytes:&[u8],cursor:&mut usize)->u32{let n=u32::from_le_bytes(bytes[*cursor..*cursor+4].try_into().unwrap());*cursor+=4;n}
fn inspect(path:&str,stage:u32,bytes:&[u8]){let words=bytes.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect::<Vec<_>>();let entries=ReflectConfig::new().spv(SpirvBinary::from(words.as_slice())).ref_all_rscs(true).combine_img_samplers(false).gen_unique_names(false).reflect().unwrap();for entry in entries{for var in entry.vars{if let Variable::Descriptor{name,desc_bind,desc_ty,ty,..}=var{if name.as_ref().is_some_and(|n|n.contains("Globals")){println!("PATH={path} STAGE={stage} ENTRY={} NAME={name:?} BINDING={desc_bind:?} KIND={desc_ty:?} BYTES={:?} TYPE={ty:?}",entry.name,ty.nbyte());}}}}}
fn main(){for path in std::env::args().skip(1){let bytes=std::fs::read(&path).unwrap();if path.ends_with(".bin"){let mut cursor=0;let count=u(&bytes,&mut cursor);for _ in 0..count{let stage=u(&bytes,&mut cursor);let name_len=u(&bytes,&mut cursor)as usize;cursor+=name_len;let nw=u(&bytes,&mut cursor)as usize;inspect(&path,stage,&bytes[cursor..cursor+nw*4]);cursor+=nw*4;}}else{inspect(&path,99,&bytes);}}}
